package it.cavallium.rockserver.core.common.distributed;

import java.io.*;
import java.util.*;

/** Receiver-local durable authorization input. Only a trusted fresh-authority adapter may install it. */
public final class NativeTopologyLearnerRegistration {
    public static final int MAX_BYTES=TopologyChange.MAX_DEFINITION_BYTES+NativeTopologyImageOrigin.MAX_BYTES+DistributedSchemaCodec.MAX_BYTES+2*65536+512+RangeDirectoryCodec.MAX_COLUMNS*4115;
    private final TopologyChange.Definition definition;
    private final NativeTopologyImageOrigin origin;
    private final DistributedSchema schema;
    private final ReplicaDescriptor receiver;
    private final UUID catalogue;
    private final ApplyPosition catalogueCut,imageCut;
    private final byte[] imageHash,sourceConfiguration,proposedConfiguration,encoded;
    private final Map<UUID,String> physicalNames;
    private final Set<UUID> mergeColumns;
    public NativeTopologyLearnerRegistration(TopologyChange.Definition definition,NativeTopologyImageOrigin origin,DistributedSchema schema,ReplicaDescriptor receiver,UUID catalogue,ApplyPosition catalogueCut,ApplyPosition imageCut,byte[] imageHash,byte[] sourceConfiguration,byte[] proposedConfiguration,Map<UUID,String> physicalNames,Set<UUID> mergeColumns) {
        this.definition=Objects.requireNonNull(definition);this.origin=Objects.requireNonNull(origin);this.schema=Objects.requireNonNull(schema);this.receiver=Objects.requireNonNull(receiver);this.catalogue=Objects.requireNonNull(catalogue);this.catalogueCut=Objects.requireNonNull(catalogueCut);this.imageCut=Objects.requireNonNull(imageCut);this.physicalNames=Map.copyOf(physicalNames);this.mergeColumns=Set.copyOf(mergeColumns);
        if(definition.kind()!=TopologyChange.Kind.RELOCATE || receiver.role()!=ReplicaDescriptor.Role.LISTENER || catalogueCut.term()<1 || catalogueCut.index()<1 || imageHash==null || imageHash.length!=32 || sourceConfiguration==null || sourceConfiguration.length<1 || sourceConfiguration.length>65536 || proposedConfiguration==null || proposedConfiguration.length<1 || proposedConfiguration.length>65536 || Arrays.equals(sourceConfiguration,proposedConfiguration))throw new IllegalArgumentException("Invalid qualified learner registration");
        var source=definition.parents().getFirst();var target=definition.targets().getFirst();schema.requireMatches(definition.sourceDirectory());schema.requireMatches(definition.targetDirectory());
        if(source.replicas().stream().anyMatch(replica->replica.replicaId().equals(receiver.replicaId())) || target.replicas().stream().noneMatch(receiver::equals) || !catalogue.equals(origin.activation().catalogueGroup()) || !this.physicalNames.keySet().equals(schema.columnIds()) || !schema.columnIds().containsAll(this.mergeColumns) || new HashSet<>(this.physicalNames.values()).size()!=this.physicalNames.size())throw new IllegalArgumentException("Learner changed receiver/schema/column identity");
        origin.requireImage(source.groupId(),source.rangeEpoch(),schema.domainId(),source.lowerInclusive(),source.upperExclusive(),imageCut);
        if(!origin.seed().header().clusterId().equals(schema.clusterId()) || !origin.seed().header().databaseId().equals(schema.databaseId()) || !origin.seed().header().domainId().equals(schema.domainId()))throw new IllegalArgumentException("Learner source provenance namespace changed");
        for(var entry:this.physicalNames.entrySet()) { String name=entry.getValue();if(name.isEmpty() || name.length()>4096 || !name.matches("[\\x20-\\x7e]+") || name.indexOf('\0')>=0)throw new IllegalArgumentException("Invalid learner CF alias");if(this.mergeColumns.contains(entry.getKey())!=(schema.column(entry.getKey()).operator()!=null))throw new IllegalArgumentException("Learner merge operator differs from qualified schema"); }
        this.imageHash=imageHash.clone();this.sourceConfiguration=sourceConfiguration.clone();this.proposedConfiguration=proposedConfiguration.clone();encoded=encodeCurrent();if(encoded.length>MAX_BYTES)throw new IllegalArgumentException("Learner registration exceeds metadata bound");
    }
    public TopologyChange.Definition definition(){return definition;}public NativeTopologyImageOrigin origin(){return origin;}public DistributedSchema schema(){return schema;}public ReplicaDescriptor receiver(){return receiver;}public UUID catalogue(){return catalogue;}public ApplyPosition catalogueCut(){return catalogueCut;}public ApplyPosition imageCut(){return imageCut;}public Map<UUID,String> physicalNames(){return physicalNames;}public Set<UUID> mergeColumns(){return mergeColumns;}
    public byte[] imageHash(){return imageHash.clone();}public byte[] sourceConfiguration(){return sourceConfiguration.clone();}public byte[] proposedConfiguration(){return proposedConfiguration.clone();}public byte[] encode(){return encoded.clone();}public byte[] digest(){return OperatorUpload.sha256(encoded);}
    private byte[] encodeCurrent(){try{var bytes=new ByteArrayOutputStream();var out=new DataOutputStream(bytes);out.writeInt(0x4e544c52);for(byte[] blob:List.of(definition.encode(),origin.encode(),DistributedSchemaCodec.encode(schema)))blob(out,blob);for(UUID id:List.of(receiver.nodeId(),receiver.nodeIncarnation(),receiver.replicaId(),catalogue)){out.writeLong(id.getMostSignificantBits());out.writeLong(id.getLeastSignificantBits());}out.writeUTF(receiver.peerId());out.writeUTF(receiver.address());out.writeLong(catalogueCut.term());out.writeLong(catalogueCut.index());out.writeLong(imageCut.term());out.writeLong(imageCut.index());out.write(imageHash);blob(out,sourceConfiguration);blob(out,proposedConfiguration);out.writeInt(physicalNames.size());for(UUID column:physicalNames.keySet().stream().sorted().toList()){out.writeLong(column.getMostSignificantBits());out.writeLong(column.getLeastSignificantBits());out.writeUTF(physicalNames.get(column));out.writeBoolean(mergeColumns.contains(column));}return bytes.toByteArray();}catch(IOException impossible){throw new AssertionError(impossible);}}
    private static void blob(DataOutputStream out,byte[] bytes)throws IOException{out.writeInt(bytes.length);out.write(bytes);}private static byte[] blob(DataInputStream in,int max)throws IOException{int size=in.readInt();if(size<1 || size>max || size>in.available())throw new IllegalArgumentException("Learner blob exceeds bound");return in.readNBytes(size);}private static UUID uuid(DataInputStream in)throws IOException{return new UUID(in.readLong(),in.readLong());}
    public static NativeTopologyLearnerRegistration decode(byte[] bytes){if(bytes==null || bytes.length<4 || bytes.length>MAX_BYTES)throw new IllegalArgumentException("Invalid learner registration length");try{var in=new DataInputStream(new ByteArrayInputStream(bytes));if(in.readInt()!=0x4e544c52)throw new IllegalArgumentException("Invalid learner registration tag");var definition=TopologyChange.Definition.decode(blob(in,TopologyChange.MAX_DEFINITION_BYTES));var origin=NativeTopologyImageOrigin.decode(blob(in,NativeTopologyImageOrigin.MAX_BYTES));var schema=DistributedSchemaCodec.decode(blob(in,DistributedSchemaCodec.MAX_BYTES));UUID node=uuid(in),incarnation=uuid(in),replica=uuid(in),catalogue=uuid(in);var receiver=new ReplicaDescriptor(node,incarnation,replica,in.readUTF(),in.readUTF(),ReplicaDescriptor.Role.LISTENER);var catalogueCut=new ApplyPosition(in.readLong(),in.readLong());var imageCut=new ApplyPosition(in.readLong(),in.readLong());byte[] hash=in.readNBytes(32);var source=blob(in,65536);var proposed=blob(in,65536);int count=in.readInt();if(count<0 || count>RangeDirectoryCodec.MAX_COLUMNS)throw new IllegalArgumentException("Learner columns exceed bound");var names=new HashMap<UUID,String>();var merges=new HashSet<UUID>();for(int n=0;n<count;n++){UUID column=uuid(in);if(names.put(column,in.readUTF())!=null)throw new IllegalArgumentException("Duplicate learner column");if(in.readBoolean())merges.add(column);}var result=new NativeTopologyLearnerRegistration(definition,origin,schema,receiver,catalogue,catalogueCut,imageCut,hash,source,proposed,names,merges);if(in.available()!=0 || !Arrays.equals(bytes,result.encoded))throw new IllegalArgumentException("Noncanonical learner registration");return result;}catch(IOException invalid){throw new IllegalArgumentException("Truncated learner registration",invalid);}}
    @Override public boolean equals(Object other){return other instanceof NativeTopologyLearnerRegistration registration && Arrays.equals(encoded,registration.encoded);}@Override public int hashCode(){return Arrays.hashCode(encoded);}
}
